from collections.abc import Iterable

def flatten_nested(lst: list) -> list:
    """Flatten arbitrarily nested lists iteratively."""
    result = []
    stack = [iter(lst)]
    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if isinstance(item, list):
            stack.append(iter(item))
        else:
            result.append(item)
    return result
```
Uses an explicit stack of iterators to avoid recursion depth limits.

