import random
from typing import Optional

def kth_largest(nums: list[int], k: int) -> Optional[int]:
    if k < 1 or k > len(nums):
        return None
    target = len(nums) - k
    def select(lo: int, hi: int) -> int:
        if lo == hi:
            return nums[lo]
        pivot_idx = random.randint(lo, hi)
        nums[pivot_idx], nums[hi] = nums[hi], nums[pivot_idx]
        pivot = nums[hi]
        store = lo
        for i in range(lo, hi):
            if nums[i] < pivot:
                nums[store], nums[i] = nums[i], nums[store]
                store += 1
        nums[store], nums[hi] = nums[hi], nums[store]
        if store == target:
            return nums[store]
        elif store < target:
            return select(store + 1, hi)
        else:
            return select(lo, store - 1)
    return select(0, len(nums) - 1)
```
Quickselect algorithm — average O(n), worst O(n²). Random pivot avoids worst-case on sorted input.

