def are_anagrams(a: str, b: str) -> bool:
    if len(a) != len(b):
        return False
    counts = [0] * 26
    for ch in a:
        counts[ord(ch) - 97] += 1
    for ch in b:
        idx = ord(ch) - 97
        counts[idx] -= 1
        if counts[idx] < 0:
            return False
    return True
```
